package com.ahadporkar.handwerkflow.api;
import com.ahadporkar.handwerkflow.domain.JobStatus;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import java.math.BigDecimal;
import java.security.Principal;
import java.util.*;
@RestController @RequestMapping("/api/v1") public class ApiController {
 private final NamedParameterJdbcTemplate db;
 public ApiController(NamedParameterJdbcTemplate db){this.db=db;}
 public record CustomerInput(@NotBlank String name,@Email String email,String phone,String address){}
 public record JobInput(@NotNull UUID customerId,@NotBlank String title,@NotBlank String trade,@NotBlank String siteAddress,String description){}
 public record SurveyInput(@NotBlank String notes,String accessRequirements,@DecimalMin("0") BigDecimal estimatedHours){}
 public record ReportInput(@NotBlank String notes,String materialsUsed,boolean safetyChecked,boolean customerAccepted){}
 public record CompletionInput(@NotBlank String description,String acknowledgedBy){}
 public record InvoiceInput(@NotBlank String description,@NotNull @DecimalMin("0") BigDecimal netAmount,@NotNull @DecimalMin("0") @DecimalMax("1") BigDecimal taxRate){}
 public record TransitionInput(@NotNull JobStatus status,@NotNull Long expectedVersion){}
 private MapSqlParameterSource args(Object... entries){var p=new MapSqlParameterSource();for(int i=0;i<entries.length;i+=2)p.addValue((String)entries[i],entries[i+1]);return p;}
 private List<Map<String,Object>> list(String sql,MapSqlParameterSource p){return db.queryForList(sql,p);}
 private Map<String,Object> one(String sql,MapSqlParameterSource p){var rows=list(sql,p);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Record not found");return rows.getFirst();}
 private UUID create(String table,String fields,String values,MapSqlParameterSource p){return db.queryForObject("INSERT INTO "+table+"("+fields+") VALUES ("+values+") RETURNING id",p,UUID.class);}
 private void event(UUID id,String type,String detail,String actor){db.update("INSERT INTO job_events(job_id,event_type,description,actor) VALUES (:id,:type,:detail,:actor)",args("id",id,"type",type,"detail",detail,"actor",actor));}
 @GetMapping("/dashboard") public Map<String,Object> dashboard(){return Map.of("jobCounts",list("SELECT status, count(*) AS count FROM jobs GROUP BY status ORDER BY status",args()),"recentJobs",list("SELECT j.id,j.title,j.trade,j.status,j.created_at,c.name AS customer_name FROM jobs j JOIN customers c ON c.id=j.customer_id ORDER BY j.created_at DESC LIMIT 8",args()),"invoiceTotals",one("SELECT COUNT(*) AS count,COALESCE(SUM(net_amount*(1+tax_rate)),0) AS gross FROM invoices",args()));}
 @GetMapping("/customers") public List<Map<String,Object>> customers(){return list("SELECT * FROM customers ORDER BY created_at DESC LIMIT 200",args());}
 @PostMapping("/customers") @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> customer(@Valid @RequestBody CustomerInput body){UUID id=create("customers","name,email,phone,address",":name,:email,:phone,:address",args("name",body.name(),"email",body.email(),"phone",body.phone(),"address",body.address()));return one("SELECT * FROM customers WHERE id=:id",args("id",id));}
 @GetMapping("/jobs") public List<Map<String,Object>> jobs(@RequestParam(required=false) JobStatus status){return list("SELECT j.*,c.name AS customer_name FROM jobs j JOIN customers c ON c.id=j.customer_id "+(status==null?"":"WHERE j.status=:status ")+"ORDER BY j.created_at DESC LIMIT 250",args("status",status==null?null:status.name()));}
 @GetMapping("/jobs/{id}") public Map<String,Object> job(@PathVariable UUID id){return one("SELECT j.*,c.name AS customer_name FROM jobs j JOIN customers c ON c.id=j.customer_id WHERE j.id=:id",args("id",id));}
 @PostMapping("/jobs") @ResponseStatus(HttpStatus.CREATED) @Transactional public Map<String,Object> job(@Valid @RequestBody JobInput body,Principal user){if(!Set.of("ELECTRICAL","HVAC","SOLAR","PLUMBING").contains(body.trade()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unknown trade");one("SELECT id FROM customers WHERE id=:id",args("id",body.customerId()));UUID id=create("jobs","customer_id,title,trade,site_address,description",":customer,:title,:trade,:address,:description",args("customer",body.customerId(),"title",body.title(),"trade",body.trade(),"address",body.siteAddress(),"description",body.description()));event(id,"CREATED","Job intake",user.getName());return job(id);}
 @PatchMapping("/jobs/{id}/status") @Transactional public Map<String,Object> transition(@PathVariable UUID id,@Valid @RequestBody TransitionInput body,Principal user){var current=job(id);var from=JobStatus.valueOf(current.get("status").toString());if(!from.canTransitionTo(body.status()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Invalid transition "+from+" -> "+body.status());if(body.status()==JobStatus.SCHEDULED && one("SELECT COUNT(*) AS n FROM surveys WHERE job_id=:id",args("id",id)).get("n").equals(0L))throw new ResponseStatusException(HttpStatus.CONFLICT,"A survey is required before scheduling");if(body.status()==JobStatus.COMPLETED && one("SELECT COUNT(*) AS n FROM installation_reports WHERE job_id=:id AND safety_checked AND customer_accepted",args("id",id)).get("n").equals(0L))throw new ResponseStatusException(HttpStatus.CONFLICT,"Accepted safety-checked report required");int updated=db.update("UPDATE jobs SET status=:status,version=version+1,updated_at=now() WHERE id=:id AND version=:version",args("status",body.status().name(),"id",id,"version",body.expectedVersion()));if(updated!=1)throw new ResponseStatusException(HttpStatus.CONFLICT,"Concurrent update; reload job");event(id,"STATUS_CHANGED",from+" -> "+body.status(),user.getName());return job(id);}
 @GetMapping("/jobs/{id}/surveys") public List<Map<String,Object>> surveys(@PathVariable UUID id){job(id);return list("SELECT * FROM surveys WHERE job_id=:id ORDER BY created_at DESC",args("id",id));}
 @PostMapping("/jobs/{id}/surveys") @ResponseStatus(HttpStatus.CREATED) @Transactional public Map<String,Object> survey(@PathVariable UUID id,@Valid @RequestBody SurveyInput b,Principal user){job(id);UUID sid=create("surveys","job_id,notes,access_requirements,estimated_hours",":id,:notes,:access,:hours",args("id",id,"notes",b.notes(),"access",b.accessRequirements(),"hours",b.estimatedHours()));event(id,"SURVEY_RECORDED","Site survey completed",user.getName());return one("SELECT * FROM surveys WHERE id=:id",args("id",sid));}
 @GetMapping("/jobs/{id}/reports") public List<Map<String,Object>> reports(@PathVariable UUID id){job(id);return list("SELECT * FROM installation_reports WHERE job_id=:id ORDER BY created_at DESC",args("id",id));}
 @PostMapping("/jobs/{id}/reports") @ResponseStatus(HttpStatus.CREATED) @Transactional public Map<String,Object> report(@PathVariable UUID id,@Valid @RequestBody ReportInput b,Principal user){job(id);UUID rid=create("installation_reports","job_id,notes,materials_used,safety_checked,customer_accepted",":id,:notes,:materials,:safe,:accepted",args("id",id,"notes",b.notes(),"materials",b.materialsUsed(),"safe",b.safetyChecked(),"accepted",b.customerAccepted()));event(id,"REPORT_RECORDED","Installation report",user.getName());return one("SELECT * FROM installation_reports WHERE id=:id",args("id",rid));}
 @GetMapping("/jobs/{id}/completions") public List<Map<String,Object>> completions(@PathVariable UUID id){job(id);return list("SELECT * FROM completion_documents WHERE job_id=:id ORDER BY completed_at DESC",args("id",id));}
 @PostMapping("/jobs/{id}/completions") @ResponseStatus(HttpStatus.CREATED) @Transactional public Map<String,Object> completion(@PathVariable UUID id,@Valid @RequestBody CompletionInput b,Principal user){var j=job(id);if(!Set.of("COMPLETED","INVOICED").contains(j.get("status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"Job must be completed");UUID cid=create("completion_documents","job_id,description,acknowledged_by",":id,:description,:by",args("id",id,"description",b.description(),"by",b.acknowledgedBy()));event(id,"COMPLETION_DOCUMENT","Completion recorded",user.getName());return one("SELECT * FROM completion_documents WHERE id=:id",args("id",cid));}
 @GetMapping("/invoices") public List<Map<String,Object>> invoices(){return list("SELECT i.*,j.title AS job_title,c.name AS customer_name FROM invoices i JOIN jobs j ON j.id=i.job_id JOIN customers c ON c.id=j.customer_id ORDER BY i.issued_at DESC",args());}
 @PostMapping("/jobs/{id}/invoice") @ResponseStatus(HttpStatus.CREATED) @Transactional public Map<String,Object> invoice(@PathVariable UUID id,@Valid @RequestBody InvoiceInput b,Principal user){var job=job(id);if(!job.get("status").equals("COMPLETED"))throw new ResponseStatusException(HttpStatus.CONFLICT,"Complete the job before invoicing");String number="HW-"+java.time.Year.now()+"-"+UUID.randomUUID().toString().substring(0,8).toUpperCase(Locale.ROOT);UUID iid=create("invoices","job_id,invoice_number,description,net_amount,tax_rate",":id,:number,:description,:net,:tax",args("id",id,"number",number,"description",b.description(),"net",b.netAmount(),"tax",b.taxRate()));db.update("UPDATE jobs SET status='INVOICED',version=version+1,updated_at=now() WHERE id=:id",args("id",id));event(id,"INVOICED",number,user.getName());return one("SELECT * FROM invoices WHERE id=:id",args("id",iid));}
 @GetMapping("/jobs/{id}/events") public List<Map<String,Object>> events(@PathVariable UUID id){job(id);return list("SELECT * FROM job_events WHERE job_id=:id ORDER BY occurred_at DESC,id DESC",args("id",id));}
}
